// Tres réplicas (A, B, C) guardan las ventas de un producto del que queda 1 solo bulto.
// La red se parte: {A, B} de un lado y {C} del otro. Marcela le pide el bulto a A; Rubén, a C.
const STOCK = 1;
const vistos = { A: ["A", "B"], B: ["A", "B"], C: ["C"] };       // a qué nodos llega cada nodo durante la partición

function dia(politica) {
  const ventas = { A: [], B: [], C: [] };                         // ventas que conoce cada réplica
  const pedir = (nodo, cliente) => {
    const alcanza = vistos[nodo];
    if (politica === "CP" && alcanza.length < 2)                  // CP: sin mayoría no se confirma nada
      return `${cliente} -> ${nodo}: RECHAZADO (ve ${alcanza.length} de 3 nodos, no hay mayoría)`;
    if (ventas[nodo].length >= STOCK) return `${cliente} -> ${nodo}: RECHAZADO (sin stock)`;
    alcanza.forEach(n => ventas[n].push(cliente));                // AP y CP: se anota en los nodos que se alcanzan
    return `${cliente} -> ${nodo}: ACEPTADO`;
  };
  console.log(`--- ${politica}`);
  console.log("  " + pedir("A", "Marcela"));
  console.log("  " + pedir("C", "Rubén"));
  // la red se arregla: dos formas de juntar lo que sabe cada réplica
  const unidas = [...new Set(Object.values(ventas).flat())];
  console.log(`  al sanar, juntando todas las ventas: ${unidas.join(" + ") || "ninguna"} (${unidas.length} vendidas, había ${STOCK})`);
  if (unidas.length > STOCK) {
    const ultima = unidas[unidas.length - 1];
    console.log(`  si en cambio gana «la última escritura»: queda solo ${ultima}, y la venta de ${unidas[0]} se pierde sin avisar`);
  }
}
dia("CP");
dia("AP");
